// ===== SETTINGS: edit once =====
const SETTINGS = {
  L0_ID: 'PASTE_L0_WORKFLOW_ID',
  FROM_EMAIL: 'you@example.com',     // the system's own address
  TEAM_EMAIL: 'you@example.com',
  HUBSPOT_PORTAL_ID: '',                   // optional, adds an "Open in HubSpot" link
};
// ===============================
// Which emails count as a lead reply?
//  - anything NOT sent by the system address, or
//  - a "Re:" reply (the system itself never sends "Re:" subjects)
// So the system's own alerts and follow-ups landing in this inbox are ignored.
function addressOf(v) {
  if (!v) return '';
  if (typeof v === 'object') {
    const a = (v.value && v.value[0] && v.value[0].address) || v.address || v.text || '';
    return addressOf(a);
  }
  const m = String(v).match(/<([^>]+)>/);
  return (m ? m[1] : String(v)).trim().toLowerCase();
}
// Machine-sent mail is never a lead reply: out-of-office, auto-replies, bounces, no-reply senders.
const AUTO_SUBJECT = /^\s*(automatic reply|auto[- ]?reply|autoreply|auto( |-)?response|auto:|out of (the )?office|ooo\b|on vacation|away from|undeliverable|undelivered|delivery (status notification|failure|has failed)|mail delivery (failed|subsystem)|returned mail|failure notice)/i;
const AUTO_SENDER = /^(mailer-daemon|postmaster|no-?reply|do-?not-?reply|bounces?|auto-?reply)([+.@-]|$)/i;
function cleanBody(t) {
  // HTML-only emails: drop tags, keep text
  t = String(t || '').replace(/<(br|\/p|\/div)\s*\/?>/gi, '\n').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ');
  // cut at the quoted thread, even when Gmail wraps "On ... wrote:" over two lines
  const cut = t.search(/(^|\n)\s*On [^\n]*(\n[^\n]*)?wrote:/);
  if (cut >= 0) t = t.slice(0, cut);
  const lines = t.split(/\r?\n/);
  const keep = [];
  for (const l of lines) {
    if (/^On .+wrote:\s*$/i.test(l.trim()) || /^-{2,}\s*Original Message/i.test(l.trim())) break;
    if (l.trim().startsWith('>')) continue;
    keep.push(l);
  }
  return keep.join(' ').replace(/\s+/g, ' ').trim().slice(0, 300);
}
const own = SETTINGS.FROM_EMAIL.toLowerCase();
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const from = addressOf(j.from || (j.metadata && j.metadata.from));
  const subject = String(j.subject || '').trim();
  const isRe = /^(re|aw|sv)\s*:/i.test(subject);
  if (!from || !/@/.test(from)) continue;
  if (from === own && !isRe) continue;               // the system's own mail
  if (/^\[(HOT|REPLY)\b/i.test(subject)) continue;   // our alerts, even if forwarded
  if (AUTO_SUBJECT.test(subject) || AUTO_SENDER.test(from)) continue;   // machines, not people (marker comes first)   // machines, not people
  out.push({ json: {
    settings: SETTINGS, from, subject: subject.slice(0, 200),
    snippet: cleanBody(j.textPlain || j.text || j.textHtml || j.html),
    search_body: {
      filterGroups: [{ filters: [{ propertyName: 'lead_key', operator: 'EQ', value: from }] }],
      properties: ['firstname', 'lastname', 'phone', 'city', 'lead_tier', 'lead_score', 'engine_status', 'followup_stage'],
      limit: 1,
    },
  } });
}
return out;

// Keep only senders who are leads in HubSpot and haven't been marked replied yet.
// (Already-replied leads don't trigger a second alert.)
const parsed = $('Settings & parse').all();
const out = [];
const done = new Set();   // two emails from the same lead in one check -> one update, one alert
$input.all().forEach((it, i) => {
  const c = (it.json.results || [])[0];
  const p = parsed[i] && parsed[i].json;
  if (!c || !p) return;
  const props = c.properties || {};
  if (props.engine_status === 'replied' || done.has(String(c.id))) return;
  done.add(String(c.id));
  out.push({ json: {
    action: 'crm_update',
    data: { contact_id: String(c.id), properties: { engine_status: 'replied' } },
    contact_id: String(c.id), from: p.from, subject: p.subject, snippet: p.snippet,
    name: [props.firstname, props.lastname].filter(Boolean).join(' ') || p.from,
    phone: props.phone || '', city: props.city || '', tier: props.lead_tier || '', score: props.lead_score || '',
    stage: props.followup_stage || '0', settings: p.settings,
  } });
});
return out;

// One Events row per reply detected.
return $('Decide').all().map(i => ({ json: { action: 'log', data: { tab: 'Events', row: {
  idempotency_key: '', dedupe_key: i.json.from, event: 'replied',
} } } }));

// Tell the team a lead replied (follow-ups for them have already stopped).
const esc = v => String(v == null ? '' : v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const F = "'DM Sans','Helvetica Neue',Arial,sans-serif", H = "'DM Serif Display',Georgia,'Times New Roman',serif";
return $('Decide').all().map(({ json: d }) => {
  const s = d.settings;
  const href = s.HUBSPOT_PORTAL_ID ? `https://app.hubspot.com/contacts/${encodeURIComponent(s.HUBSPOT_PORTAL_ID)}/record/0-1/${encodeURIComponent(d.contact_id)}` : '';
  const btn = href ? `<a href="${esc(href)}" style="display:inline-block;padding:12px 20px;border-radius:8px;background:#145A55;color:#FFFFFF;font-family:${F};font-size:16px;line-height:20px;font-weight:700;text-decoration:none">Open in HubSpot</a>` : '';
  const tierBadge = d.tier ? `<span style="display:inline-block;padding:4px 10px;border-radius:999px;background:${d.tier === 'hot' ? '#E0A21B' : '#EEF4F2'};color:#0F2624;font-weight:700;margin-right:8px">${esc(d.tier[0].toUpperCase() + d.tier.slice(1))} ${esc(d.score)}</span>` : '';
  const rows = [['From', d.from], ['Phone', d.phone || '—'], ['City', d.city || '—'], ['Follow-ups sent', `${d.stage} of 3`], ['Subject', d.subject]]
    .map(([k, v]) => `<tr><td style="padding:8px 16px 8px 0;border-top:1px solid #DFE6E4;font-family:${F};font-size:14px;line-height:20px;color:#4E6260;vertical-align:top;white-space:nowrap">${k}</td><td style="padding:8px 0;border-top:1px solid #DFE6E4;font-family:${F};font-size:16px;line-height:24px;color:#0F2624">${esc(v)}</td></tr>`).join('');
  const html = `<!doctype html><html><body style="margin:0;padding:0;background:#F6F8F7">
<span style="display:none;max-height:0;overflow:hidden">Follow-ups are stopped. Take it from here.</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F6F8F7"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#FFFFFF;border:1px solid #DFE6E4;border-radius:12px">
<tr><td style="height:4px;line-height:4px;font-size:0;background:#145A55;border-radius:12px 12px 0 0">&nbsp;</td></tr>
<tr><td style="padding:24px 32px 0;font-family:${F};font-size:14px;line-height:20px;color:#4E6260">${tierBadge}Lead Engine, ${esc(s.BRAND)}</td></tr>
<tr><td style="padding:16px 32px 0;font-family:${H};font-size:28px;line-height:36px;color:#0F2624">${esc(d.name)} replied</td></tr>
<tr><td style="padding:8px 32px 16px;font-family:${F};font-size:16px;line-height:26px;color:#0F2624">Automatic follow-ups are stopped. Take it from here.</td></tr>
<tr><td style="padding:0 32px 16px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF4F2;border-radius:8px"><tr><td style="padding:16px 20px;font-family:${F};font-size:16px;line-height:26px;color:#0F2624"><div style="font-size:14px;line-height:20px;font-weight:700;margin-bottom:4px">They wrote</div>${esc(d.snippet || '(no text)')}</td></tr></table></td></tr>
<tr><td style="padding:0 32px 8px">${btn}</td></tr>
<tr><td style="padding:8px 32px 24px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${rows}</table></td></tr>
</table></td></tr></table></body></html>`;
  return { json: {
    to: s.TEAM_EMAIL, from: `Lead Engine <${s.FROM_EMAIL}>`,
    subject: `[REPLY] ${d.name} replied: follow-ups stopped`,
    html,
  } };
});
